// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PlatformPlugin) predicate.PlatformPlugin {
	return predicate.PlatformPlugin(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PlatformPlugin) predicate.PlatformPlugin {
	return predicate.PlatformPlugin(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PlatformPlugin) predicate.PlatformPlugin {
	return predicate.PlatformPlugin(sql.NotPredicates(p))
}
